package cn.lili.modules.community.p0.fulfillment;
import cn.lili.common.security.session.SessionDomain;
import cn.lili.modules.community.p0.agreement.AgreementService;
import cn.lili.modules.community.p0.support.*;
import com.google.gson.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import java.time.*;
import java.util.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;

@Service
@cn.lili.modules.community.p0.support.P0BusinessEnabled
public class FulfillmentService {
    private final Stage1Db db;private final Stage1Context context;private final Stage1Mutations mutations;private final Stage1Regions regions;private final Clock clock;
    public FulfillmentService(Stage1Db db,Stage1Context context,Stage1Mutations mutations,Stage1Regions regions,@Qualifier("stage1Clock") Clock clock){this.db=db;this.context=context;this.mutations=mutations;this.regions=regions;this.clock=clock;}
    public Object configuration(String store){authorizedStore(store);var row=db.one("SELECT * FROM li_p0_fulfillment_config WHERE store_id=?",store);return map("storeId",store,"version",row==null?0:number(row,"version"),"methods",row==null?new JsonObject():object(row.get("methods")),"effectiveMethods",effective(store).keySet(),"history",db.rows("SELECT version,methods,reason,created_at FROM li_p0_fulfillment_history WHERE store_id=? ORDER BY version DESC LIMIT 50",store).stream().map(r->map("version",r.get("version"),"methods",object(r.get("methods")),"reason",r.get("reason"),"at",instant(r.get("created_at")))).toList());}
    public Object saveConfiguration(Object body){
        var actor=context.require(SessionDomain.STORE);var f=new Fields(body).only("requestId","expectedVersion","methods","reason");String reason=f.text("reason",1,500,true);return mutations.run("fulfillment.save",body,actor.store(),()->{
            var old=db.one("SELECT * FROM li_p0_fulfillment_config WHERE store_id=?",actor.store());Stage1Exception.require((old==null?0:number(old,"version"))==f.version(),409,"VERSION_CONFLICT");var input=new Fields(f.child("methods",true)).only(Stage1Rules.METHODS.toArray(String[]::new));JsonObject methods=new JsonObject();
            for(String method:new TreeSet<>(Stage1Rules.METHODS)){
                var value=new Fields(input.child(method,true)).only("enabled","feeCent","nationwide","districtCodes","excludedDistrictCodes","description");Stage1Exception.require(value.has("enabled"),422,"METHOD_ENABLED_REQUIRED");boolean enabled=value.bool("enabled",false),delivery=Set.of("MERCHANT_DELIVERY","EXPRESS").contains(method);Long fee=value.integer("feeCent",0,999999,enabled&&delivery);value.text("description",0,500,false);
                List<String> districts=regionCodes(value,"districtCodes"),excluded=regionCodes(value,"excludedDistrictCodes");boolean nationwide=value.bool("nationwide",false);
                if(delivery){if(method.equals("MERCHANT_DELIVERY"))Stage1Exception.require(!nationwide&&excluded.isEmpty(),422,"DELIVERY_SCOPE_INVALID");if(nationwide)Stage1Exception.require(districts.isEmpty(),422,"EXPRESS_SCOPE_CONFLICT");else{Stage1Exception.require(excluded.isEmpty(),422,"EXPRESS_SCOPE_CONFLICT");if(enabled)Stage1Exception.require(!districts.isEmpty(),422,"DELIVERY_SCOPE_REQUIRED");}}
                else{Stage1Exception.require((fee==null||fee==0)&&!nationwide&&districts.isEmpty()&&excluded.isEmpty(),422,"POINT_METHOD_FREE_ONLY");if(enabled)Stage1Exception.require(!effectivePoints(actor.store(),method).isEmpty(),422,"ENABLED_POINT_REQUIRED");}
                methods.add(method,object(map("enabled",enabled,"feeCent",delivery?fee:Long.valueOf(0),"nationwide",nationwide,"districtCodes",districts,"excludedDistrictCodes",excluded,"description",value.text("description",0,500,false))));
            }
            if(closed(actor.store())){
                Stage1Exception.require(old!=null,403,"STORE_CLOSED");var previous=object(old.get("methods"));for(String method:methods.keySet()){var before=previous.getAsJsonObject(method);var after=methods.getAsJsonObject(method);Stage1Exception.require(before!=null&&(!after.get("enabled").getAsBoolean()||before.get("enabled").getAsBoolean()),403,"STORE_CLOSED_EXPANSION_FORBIDDEN");var a=after.deepCopy();var b=before.deepCopy();a.remove("enabled");b.remove("enabled");Stage1Exception.require(hash(a).equals(hash(b)),403,"STORE_CLOSED_CONFIGURATION_RESTRICTED");}
            }
            if(old==null)db.update("INSERT INTO li_p0_fulfillment_config(store_id,version,methods,updated_at) VALUES(?,1,?,?)",actor.store(),write(methods),clock.instant());else db.cas(db.update("UPDATE li_p0_fulfillment_config SET version=version+1,methods=?,updated_at=? WHERE store_id=? AND version=?",write(methods),clock.instant(),actor.store(),f.version()));
            db.update("INSERT INTO li_p0_fulfillment_history(store_id,version,methods,actor_id,reason,created_at) VALUES(?,?,?,?,?,?)",actor.store(),f.version()+1,write(methods),actor.id(),reason,clock.instant());mutations.audit("fulfillment.save",actor.store(),actor.store(),f.requestId(),f.version(),f.version()+1,reason);mutations.invalidated(actor.store(),actor.store(),"FULFILLMENT",f.version()+1);return configuration(actor.store());
        });
    }
    private List<String> regionCodes(Fields f,String key){List<String> codes=new ArrayList<>();for(var item:f.list(key,0,5000,false)){String code=new Fields(map("code",item)).text("code",6,6,true);Stage1Exception.require(code.matches("[0-9]{6}")&&!codes.contains(code),422,"REGION_DUPLICATE_OR_INVALID");db.required("SELECT id FROM li_region WHERE ad_code=? AND level='district' AND delete_flag=0",code);codes.add(code);}return codes;}
    public Object savePoint(String id,Object body){
        var actor=context.require(SessionDomain.STORE);var f=new Fields(body).only("requestId","expectedVersion","type","name","provinceCode","cityCode","districtCode","address","contactName","phone","opening","instructions","coordinates","reason");String reason=f.text("reason",1,500,true);
        return mutations.run("point.save:"+id,body,actor.store(),()->{
            var previous=id==null?null:point(id,actor.store());if(id==null)Stage1Exception.require(!closed(actor.store()),403,"STORE_CLOSED");else Stage1Exception.require(number(previous,"version")==f.version(),409,"VERSION_CONFLICT");
            String type=f.choice("type",Set.of("COMMUNITY_PICKUP","STORE_REDEMPTION"),true),name=f.text("name",2,40,true),address=f.text("address",5,200,true),contact=f.text("contactName",2,30,true),phone=f.text("phone",7,20,true);Stage1Rules.phone(phone);regions.address(f,true);String instructions=f.text("instructions",0,500,false);var opening=opening(f.child("opening",true));
            if(previous!=null)Stage1Exception.require(type.equals(id(previous,"type")),422,"POINT_TYPE_IMMUTABLE");String center=null;
            if(f.has("coordinates")){var coordinates=new Fields(f.child("coordinates",true)).only("longitudeMillionths","latitudeMillionths");center=write(map("longitudeMillionths",coordinates.integer("longitudeMillionths",-180000000,180000000,true),"latitudeMillionths",coordinates.integer("latitudeMillionths",-90000000,90000000,true)));}
            String target=id==null?db.id():id;
            if(id==null){db.nativeInsert("li_store_address",map("id",target,"create_by",actor.id(),"create_time",clock.instant(),"delete_flag",false,"address",address,"address_name",name,"center",center,"mobile",phone,"store_id",actor.store()));db.update("INSERT INTO li_p0_point_control(point_id,store_id,type,province_code,city_code,district_code,contact_name,opening_description,opening_hours,instructions,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",target,actor.store(),type,f.text("provinceCode",6,6,true),f.text("cityCode",6,6,true),f.text("districtCode",6,6,true),contact,write(opening),write(opening),instructions,clock.instant());}
            else{db.update("UPDATE li_store_address SET address=?,address_name=?,center=?,mobile=?,update_by=?,update_time=? WHERE id=? AND store_id=?",address,name,center,phone,actor.id(),clock.instant(),id,actor.store());db.cas(db.update("UPDATE li_p0_point_control SET province_code=?,city_code=?,district_code=?,contact_name=?,opening_description=?,opening_hours=?,instructions=?,enabled=IF(?,0,enabled),version=version+1 WHERE point_id=? AND store_id=? AND version=?",f.text("provinceCode",6,6,true),f.text("cityCode",6,6,true),f.text("districtCode",6,6,true),contact,write(opening),write(opening),instructions,closed(actor.store()),id,actor.store(),f.version()));}
            history(target,actor.store());mutations.audit("point.save",actor.store(),target,f.requestId(),id==null?null:f.version(),id==null?0L:f.version()+1,reason);mutations.invalidated(actor.store(),target,"POINT",id==null?0:f.version()+1);return pointView(point(target,actor.store()),false);
        });
    }
    private JsonObject opening(Object input){
        var f=new Fields(input).only("weekdays","allDay","start","end","crossDay");Set<Long> days=new TreeSet<>();for(var item:f.list("weekdays",1,7,true)){long day=new Fields(map("value",item)).integer("value",1,7,true);Stage1Exception.require(days.add(day),422,"OPENING_DAY_DUPLICATE");}boolean all=f.bool("allDay",false),cross=f.bool("crossDay",false);String start=f.text("start",5,5,!all),end=f.text("end",5,5,!all);
        if(all)Stage1Exception.require(start==null&&end==null&&!cross,422,"OPENING_ALL_DAY_CONFLICT");else try{Stage1Exception.require(start.matches("[0-2][0-9]:[0-5][0-9]")&&end.matches("[0-2][0-9]:[0-5][0-9]"),422,"OPENING_TIME_INVALID");var a=LocalTime.parse(start);var b=LocalTime.parse(end);Stage1Exception.require(cross?b.isBefore(a):b.isAfter(a),422,"OPENING_RANGE_INVALID");}catch(DateTimeException invalid){throw new Stage1Exception(422,"OPENING_TIME_INVALID");}
        return object(map("weekdays",days,"allDay",all,"start",start,"end",end,"crossDay",cross));
    }
    public Object pointCommand(String id,Object body,boolean enable){var actor=context.require(SessionDomain.STORE);var f=new Fields(body).only("requestId","expectedVersion","reason");String reason=f.text("reason",1,500,true);return mutations.run("point."+(enable?"enable":"disable")+":"+id,body,actor.store(),()->{var row=point(id,actor.store());if(enable){Stage1Exception.require(!closed(actor.store()),403,"STORE_CLOSED");Stage1Exception.require(pointComplete(row),422,"POINT_INCOMPLETE");}db.cas(db.update("UPDATE li_p0_point_control SET enabled=?,version=version+1 WHERE point_id=? AND store_id=? AND version=?",enable,id,actor.store(),f.version()));history(id,actor.store());mutations.audit("point."+(enable?"enable":"disable"),actor.store(),id,f.requestId(),f.version(),f.version()+1,reason);mutations.invalidated(actor.store(),id,"POINT",f.version()+1);return pointView(point(id,actor.store()),false);});}
    private boolean pointComplete(Map<String,Object> row){
        return pointIssues(row).isEmpty();
    }
    public boolean isAvailablePoint(Map<String,Object> row,String type){return type.equals(id(row,"type"))&&flag(row,"enabled")&&pointComplete(row);}
    private List<String> pointIssues(Map<String,Object> row){
        var f=new Fields(map("name",row.get("address_name"),"address",row.get("address"),"contactName",row.get("contact_name"),"phone",row.get("mobile"),"provinceCode",row.get("province_code"),"cityCode",row.get("city_code"),"districtCode",row.get("district_code")));var issues=new ArrayList<String>();
        for(var field:Map.of("name",new int[]{2,40},"address",new int[]{5,200},"contactName",new int[]{2,30}).entrySet())try{f.text(field.getKey(),field.getValue()[0],field.getValue()[1],true);}catch(Stage1Exception invalid){issues.add(field.getKey());}
        try{Stage1Rules.phone(f.text("phone",7,20,true));}catch(Stage1Exception invalid){issues.add("phone");}
        try{regions.address(f,true);}catch(Stage1Exception invalid){issues.add("region");}
        try{Stage1Exception.require(row.get("opening_hours")!=null,422,"POINT_INCOMPLETE");opening(object(row.get("opening_hours")));}catch(Stage1Exception invalid){issues.add("opening");}
        return issues;
    }
    private void history(String id,String store){var row=point(id,store);db.update("INSERT INTO li_p0_point_history(point_id,version,snapshot,created_at) VALUES(?,?,?,?)",id,number(row,"version"),write(pointView(row,false)),clock.instant());}
    public Map<String,Object> point(String id,String store){return db.required("SELECT a.*,p.type,p.enabled,p.version,p.province_code,p.city_code,p.district_code,p.contact_name,p.opening_hours,p.instructions FROM li_store_address a JOIN li_p0_point_control p ON p.point_id=a.id AND p.store_id=a.store_id WHERE a.id=? AND a.store_id=? AND a.delete_flag=0",id,store);}
    public Object points(String store,String type,Boolean enabled,int page,int size){authorizedStore(store);AgreementService.page(page,size);if(type!=null)Stage1Exception.require(Set.of("COMMUNITY_PICKUP","STORE_REDEMPTION").contains(type),422,"POINT_TYPE_INVALID");String where=" FROM li_p0_point_control p JOIN li_store_address a ON a.id=p.point_id WHERE p.store_id=? AND a.delete_flag=0 AND (? IS NULL OR p.type=?) AND (? IS NULL OR p.enabled=?)";return map("total",db.count("SELECT COUNT(*)"+where,store,type,type,enabled,enabled),"records",db.rows("SELECT p.point_id"+where+" ORDER BY COALESCE(a.update_time,a.create_time) DESC,p.point_id DESC LIMIT ? OFFSET ?",store,type,type,enabled,enabled,size,(page-1)*size).stream().map(r->pointView(point(id(r,"point_id"),store),false)).toList());}
    public Object detail(String id){var actor=context.require(SessionDomain.STORE);var row=point(id,actor.store());return map("point",pointView(row,false),"history",db.rows("SELECT version,snapshot,created_at FROM li_p0_point_history WHERE point_id=? ORDER BY version DESC",id).stream().map(r->map("version",r.get("version"),"snapshot",object(r.get("snapshot")),"at",instant(r.get("created_at")))).toList());}
    public List<Map<String,Object>> effectivePoints(String store,String type){return db.rows("SELECT p.point_id FROM li_p0_point_control p JOIN li_store_address a ON a.id=p.point_id WHERE p.store_id=? AND p.type=? AND p.enabled=1 AND p.opening_hours IS NOT NULL AND a.delete_flag=0 ORDER BY p.point_id",store,type).stream().map(r->point(id(r,"point_id"),store)).filter(this::pointComplete).toList();}
    public Map<String,JsonObject> effective(String store){
        var row=db.one("SELECT methods FROM li_p0_fulfillment_config WHERE store_id=?",store);if(row==null||closed(store))return Map.of();var f=new Fields(row.get("methods"));Map<String,JsonObject> methods=new TreeMap<>();for(String type:Stage1Rules.METHODS){var method=new Fields(f.child(type,false));if(!method.bool("enabled",false))continue;if(Set.of("COMMUNITY_PICKUP","STORE_REDEMPTION").contains(type)&&effectivePoints(store,type).isEmpty())continue;methods.put(type,method.json());}return methods;
    }
    public void requireConfigured(String store,Collection<String> chosen){var available=effective(store);Stage1Exception.require(!chosen.isEmpty()&&available.keySet().containsAll(chosen),422,"FULFILLMENT_CONFIGURATION_REQUIRED");}
    public boolean supports(JsonObject config,String district){var f=new Fields(config);var allowed=f.list("districtCodes",0,5000,false).asList().stream().map(JsonElement::getAsString).toList();var excluded=f.list("excludedDistrictCodes",0,5000,false).asList().stream().map(JsonElement::getAsString).toList();return f.bool("nationwide",false)?!excluded.contains(district):allowed.contains(district);}
    public long version(String store){var row=db.one("SELECT version FROM li_p0_fulfillment_config WHERE store_id=?",store);return row==null?0:number(row,"version");}
    public Object pointView(Map<String,Object> row,boolean publicView){String id=id(row,"id"),type=id(row,"type"),store=id(row,"store_id");var result=map("id",id,"storeId",store,"type",type,"name",row.get("address_name"),"address",row.get("address"),"provinceCode",row.get("province_code"),"cityCode",row.get("city_code"),"districtCode",row.get("district_code"),"phone",publicView?maskPhone(id(row,"mobile")):row.get("mobile"),"opening",row.get("opening_hours")==null?null:object(row.get("opening_hours")),"instructions",row.get("instructions"),"enabled",flag(row,"enabled"),"version",row.get("version"));if(!publicView){var issues=pointIssues(row);result.putAll(map("complete",issues.isEmpty(),"incompleteFields",issues));}if(!publicView)result.putAll(map("contactName",row.get("contact_name"),"coordinates",row.get("center")==null?null:object(row.get("center")),"affectedGoods",db.count("SELECT COUNT(*) FROM li_p0_goods_control WHERE store_id=? AND JSON_CONTAINS(methods,JSON_QUOTE(?))",store,type)));return result;}
    private boolean closed(String store){return !"OPEN".equals(id(db.required("SELECT store_disable FROM li_store WHERE id=? AND delete_flag=0",store),"store_disable"));}
    private void authorizedStore(String store){var actor=context.current();if(actor.domain()==SessionDomain.STORE)Stage1Exception.require(store.equals(actor.store()),404,"RESOURCE_NOT_FOUND");else context.require(SessionDomain.MANAGER);}
    private static String maskPhone(String phone){return phone==null?null:phone.length()<7?"****":phone.substring(0,3)+"****"+phone.substring(phone.length()-4);}
}
